/**
 * The catalog of a live session: every tool `call` can run, as AI SDK tools.
 * `observe` shows the whole screen, the grammar is what the target's engine
 * honors, `screenshot` (which also saves a file when given a path) and the
 * point tools (`tap_at`, `hover_at`, `drag_at`, `type_at`, `press_at`,
 * `select_at`) among it, `locate` tries a semantic
 * locator the way a test would, `run_code` runs whole test statements on
 * the session's fixtures, `test_lines` returns the test line every action
 * printed (`test-lines.ts`) and the statements `run_code` passed,
 * `start_recording` and `stop_recording` follow when the engine records video,
 * and the project's own tools come last. The config load refuses a project
 * tool named like a built-in; should one reach here anyway, the built-in
 * wins and the project tool is neither listed nor reachable, the precedence
 * the testing agent's toolset applies.
 */
import { copyFileSync, mkdirSync, rmSync } from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import { projectTools } from '../agent/default-agent.js';
import { projectTree, redactNode } from '../agent/observation.js';
import { GRAMMAR_TOOL_NAMES } from '../agent/action-names.js';
import { grammarTools } from '../agent/primitives.js';
import { ConfigurationError } from '../internal/errors.js';
import { relativeToProjectRoot } from '../internal/paths.js';
import { describeExpression, roleQuery, testIdQuery, textQuery } from '../locator/expression.js';
import { recordingTools } from './recording.js';
import { SessionTestLines } from './test-lines.js';
import { runCodeTool } from './run-code.js';
/** How many matching nodes `locate` describes. */
const MAX_LOCATE_NODES = 10;
/** True for a grammar tool name, whether or not this session's engine declares the verb: a missing one is not a typo. */
export function isGrammarVerb(name) {
    return GRAMMAR_TOOL_NAMES.has(name);
}
/** Builds the session's catalog from the step context and the target. */
export function createSessionCatalog(options) {
    const { screen, locator } = options;
    const lines = new SessionTestLines({
        query: locateQuery,
        resolve: (expression) => locator.resolveNow(expression),
        read: (ref) => options.session.read(ref, locator.operation()),
        redact: options.redaction.redact,
        appBase: options.appBase,
        fills: options.fills,
        testRan: options.testRan,
    });
    const context = lines.watch(options.context);
    // The grammar's own observe reports a diff for the model loop; the
    // session's shows the whole screen, so it replaces the grammar's.
    const { observe: _diffObserve, ...verbs } = grammarTools(context, {
        screen,
        onActionFailed: options.onActionFailed,
        saveScreenshot: (file) => saveScreenshot(options, file),
    });
    const recording = options.recorder === undefined ? {} : recordingTools(options.recorder);
    const builtIn = {
        observe: fullObserveTool(context, screen),
        ...lines.wrap(verbs),
        locate: locateTool(locator, options.session, options.redaction),
        ...(options.runCode === undefined ? {} : { run_code: runCodeTool({ ...options.runCode, context, screen, record: (passed) => lines.ran(passed) }) }),
        test_lines: lines.tool(),
        ...recording,
    };
    const defined = options.tools;
    const readOnly = new Set(['observe', 'locate', 'test_lines', 'screenshot']);
    const project = {};
    for (const [name, tool] of Object.entries(projectTools(context, defined))) {
        if (name in builtIn) {
            options.warn(`project tool "${name}" is not served over MCP: the name belongs to a built-in session tool`);
            continue;
        }
        project[name] = tool;
        if (defined[name]?.annotations.mutates === false)
            readOnly.add(name);
    }
    return { tools: { ...builtIn, ...project }, readOnly, project: new Set(Object.keys(project)), context, lines };
}
/**
 * Saves the engine's masked screenshot, the one `app.screenshot` keeps, to
 * `file` resolved against the project root, and returns the absolute path.
 * As with `upload`, a path outside the project or under a hidden directory
 * is refused.
 */
async function saveScreenshot(options, file) {
    const destination = path.resolve(options.projectRoot, file);
    const relative = relativeToProjectRoot(options.projectRoot, destination);
    if (relative === undefined)
        throw new ConfigurationError('POLICY_DENIED', `${JSON.stringify(file)} is outside the project root; screenshots are saved inside the project`);
    if (relative.split(path.sep).some((segment) => segment.startsWith('.'))) {
        throw new ConfigurationError('POLICY_DENIED', `${JSON.stringify(file)} is a hidden file or sits under a hidden directory; screenshots are never saved there`);
    }
    const source = path.join(options.attemptDir, await options.session.artifacts.screenshot(path.basename(destination, path.extname(destination)), options.locator.operation()));
    mkdirSync(path.dirname(destination), { recursive: true });
    copyFileSync(source, destination);
    rmSync(source, { force: true });
    return destination;
}
/**
 * The session's `observe`: the whole screen, every time. Action results
 * report what changed since the screen the agent last received, as they do
 * for the testing agent; a coding agent that asks to look wants everything,
 * and the presenter takes that screen as the new baseline for later changes.
 */
function fullObserveTool(context, screen) {
    return {
        description: 'Look at the whole current screen: every node with its id, role, name, and state. Action results report only what changed since the screen you last received; call this to see everything again or after waiting for something in progress.',
        inputSchema: z.object({}).strict(),
        execute: async () => screen.initial(await context.observe()),
    };
}
/** The session's `locate`: a semantic locator tried against the live screen, with the verdict a test would get. */
function locateTool(locator, session, redaction) {
    return {
        description: 'Try a semantic locator against the live screen before writing it into a test: screen.getByRole(role, name), getByText, getByLabel, getByPlaceholder, or getByTestId. Returns how many nodes match and which, plus the test code to use. Exactly one of role, text, label, placeholder, or testId; name narrows a role query. Matching is exact unless exact is false.',
        inputSchema: z.object({
            role: z.string().min(1).optional().describe('ARIA role, e.g. "button", "textbox", "link"'),
            name: z.string().min(1).optional().describe('Accessible name, with role'),
            text: z.string().min(1).optional(),
            label: z.string().min(1).optional(),
            placeholder: z.string().min(1).optional(),
            testId: z.string().min(1).optional(),
            exact: z.boolean().optional().describe('false for substring, case-insensitive matching'),
        }).strict(),
        execute: async (args) => {
            const query = locateQuery(args);
            const refs = await locator.resolveNow(query.expression);
            const read = [];
            for (const ref of refs.slice(0, MAX_LOCATE_NODES)) {
                read.push(await session.read(ref, locator.operation()));
            }
            return describeLocate(query, refs.length, read, redaction);
        },
    };
}
/** Builds the expression and the matching `screen.*` call from the tool arguments. */
export function locateQuery(args) {
    const exact = args.exact !== false;
    const { role, name, text, label, placeholder, testId } = args;
    const given = [role, text, label, placeholder, testId].filter((value) => value !== undefined).length;
    if (given !== 1) {
        throw new ConfigurationError('INVALID_ARGUMENT', 'locate needs exactly one of role, text, label, placeholder, or testId');
    }
    const notFound = `Check the accessible name in the observation (observe)${exact ? ', or loosen the match with exact: false' : ''}.`;
    if (role !== undefined) {
        const options = name === undefined ? '' : `, ${JSON.stringify(name)}${exact ? '' : ', { exact: false }'}`;
        return {
            expression: roleQuery(role, name === undefined ? undefined : { name, exact }, undefined),
            code: `screen.getByRole(${JSON.stringify(role)}${options})`,
            notFound: name !== undefined && CONTENT_NAMED_ROLES.has(role) ? contentNameNotFound(role, name, exact) : notFound,
        };
    }
    if (name !== undefined)
        throw new ConfigurationError('INVALID_ARGUMENT', 'name only narrows a role query');
    if (testId !== undefined)
        return { expression: testIdQuery(testId, undefined, undefined), code: `screen.getByTestId(${JSON.stringify(testId)})`, notFound };
    const options = exact ? '' : `, { exact: false }`;
    if (text !== undefined)
        return { expression: textQuery('text', text, { exact }, undefined), code: `screen.getByText(${JSON.stringify(text)}${options})`, notFound };
    if (label !== undefined)
        return { expression: textQuery('label', label, { exact }, undefined), code: `screen.getByLabel(${JSON.stringify(label)}${options})`, notFound };
    return { expression: textQuery('placeholder', placeholder, { exact }, undefined), code: `screen.getByPlaceholder(${JSON.stringify(placeholder)}${options})`, notFound };
}
/**
 * Roles `observe` names from their text even though the platform gives them no
 * accessible name, so a message or list row reads as one line. A name read off
 * such a node is text no role query matches.
 */
const CONTENT_NAMED_ROLES = new Set(['status', 'alert', 'listitem']);
/** The zero-match advice for a content-named role: match the text instead of retrying it as a name. */
function contentNameNotFound(role, name, exact) {
    const quoted = JSON.stringify(name);
    const article = /^[aeiou]/.test(role) ? 'an' : 'a';
    const text = `screen.getByText(${quoted}${exact ? '' : ', { exact: false }'})`;
    return `A role query matches the accessible name only, and observe shows ${article} ${role} by its text in its place. If ${quoted} is that text, use screen.getByRole(${JSON.stringify(role)}).filter({ hasText: ${quoted} }) or ${text}.${exact ? ' Otherwise loosen the match with exact: false.' : ''}`;
}
/** Renders a locate result: the count, the verdict a test would get, and the nodes, each through the attempt's redactor. */
export function describeLocate(query, count, nodes, redaction) {
    const lines = [`${count === 1 ? '1 node matches' : `${count} nodes match`} ${describeExpression(query.expression)}.`];
    if (count === 1)
        lines.push(`Use: ${query.code}`);
    else if (count === 0)
        lines.push(`A test using this locator would fail with LOCATOR_NOT_FOUND. ${query.notFound}`);
    else
        lines.push(`A test action on ${query.code} would fail with LOCATOR_AMBIGUOUS. Narrow it with a name, getByRole(role, name), .filter({ hasText }), .first(), or .nth(i), or scope it under a container.`);
    for (const node of nodes)
        lines.push(`- ${describeNode(projectTree(redactNode(node, redaction)))}`);
    if (count > nodes.length)
        lines.push(`- and ${count - nodes.length} more`);
    return lines.join('\n');
}
/**
 * A located node by what names it, from the projection `observe` hands an
 * executor: name, text, and value have passed the secret ledger and a secure
 * node carries no value. Located refs are not observation ids, so none is shown.
 */
function describeNode(node) {
    const parts = [node.role ?? 'node'];
    if (node.name !== undefined && node.name !== '')
        parts.push(JSON.stringify(node.name));
    if (node.text !== undefined && node.text !== '' && node.text !== node.name)
        parts.push(`text ${JSON.stringify(node.text)}`);
    if (node.value !== undefined)
        parts.push(`value ${JSON.stringify(node.value)}`);
    const states = Object.entries(node.states ?? {})
        .filter(([, value]) => value === true)
        .map(([key]) => key);
    if (states.length > 0)
        parts.push(`[${states.join(', ')}]`);
    return parts.join(' ');
}
